// Query: status=SHIPPED, customerId=42, sort by createdAt, total > 100
db.orders.createIndex({ status: 1, customerId: 1, createdAt: 1, total: 1 });

// ESR order: equality (status, customerId) -> sort (createdAt) -> range (total)

