Broken without happens-before

  // Thread A
  x = 1;
  flag = true;   // non-volatile

  // Thread B
  if (flag) {
      int y = x;  // may see y = 0 (write not visible)
  }

Fixed with volatile

  volatile boolean flag;
  int x;

  // Thread A
  x = 1;         // write before volatile write
  flag = true;   // volatile write -- publishes x

  // Thread B
  if (flag) {    // volatile read
      int y = x; // GUARANTEED to see x = 1
  }

  Why: volatile write happens-before volatile read, and
       program order gives x = 1 --> flag = true.
       By transitivity: x = 1 happens-before y = x.

Fixed with synchronized

  // Thread A
  synchronized (lock) {
      x = 1;
      flag = true;
  }

  // Thread B
  synchronized (lock) {
      if (flag) { int y = x; }   // sees x = 1
  }

  Why: monitor release happens-before monitor acquire
       on the same lock.

count++ is NOT atomic

  volatile int count;
  // three steps: read count, add 1, write count
  // two threads can both read 0, both write 1 -- lost increment

  AtomicInteger count = new AtomicInteger();
  count.incrementAndGet();   // atomic CAS

  // or
  synchronized (this) { count++; }

The eight happens-before rules

  1. Program order      within a thread, actions are ordered
  2. Monitor lock       release of monitor hb acquire of same monitor
  3. Volatile           write to volatile hb subsequent read
  4. Thread start       Thread.start() hb every action in started thread
  5. Thread join        every action in thread hb join() return
  6. Transitivity       A hb B, B hb C  =>  A hb C
  7. Interruption       Thread.interrupt() hb interrupted-thread sees it
  8. Final fields       correct construction publishes finals safely
                       (no reference to this escaping during construction)

ReentrantLock with tryLock and timeout

  ReentrantLock lock = new ReentrantLock(true);  // fair

  void transfer(Account from, Account to, long amt)
          throws InterruptedException {
      while (true) {
          if (from.lock.tryLock(100, TimeUnit.MILLISECONDS)) {
              try {
                  if (to.lock.tryLock(100, TimeUnit.MILLISECONDS)) {
                      try {
                          if (from.balance >= amt) {
                              from.balance -= amt;
                              to.balance   += amt;
                          }
                          return;
                      } finally { to.lock.unlock(); }
                  }
              } finally { from.lock.unlock(); }
          }
          // timeout: retry (avoids deadlock without lock ordering)
      }
  }

Conditions (producer-consumer)

  ReentrantLock lock = new ReentrantLock();
  Condition notFull  = lock.newCondition();
  Condition notEmpty = lock.newCondition();

  void put(T item) throws InterruptedException {
      lock.lock();
      try {
          while (queue.size() == capacity) notFull.await();
          queue.add(item);
          notEmpty.signal();
      } finally { lock.unlock(); }
  }

  T take() throws InterruptedException {
      lock.lock();
      try {
          while (queue.isEmpty()) notEmpty.await();
          T item = queue.remove();
          notFull.signal();
          return item;
      } finally { lock.unlock(); }
  }

ReadWriteLock

  ReadWriteLock rw = new ReentrantReadWriteLock();
  Lock r = rw.readLock();
  Lock w = rw.writeLock();

  V read(K key) {
      r.lock();
      try { return cache.get(key); }
      finally { r.unlock(); }
  }

  void write(K key, V val) {
      w.lock();
      try { cache.put(key, val); }
      finally { w.unlock(); }
  }

  // NO lock upgrade -- deadlock
  // r.lock(); w.lock();   <- illegal

  // Lock downgrade is allowed
  // w.lock(); r.lock(); w.unlock();   <- ok, still holding r

StampedLock optimistic read

  StampedLock sl = new StampedLock();
  double x, y;

  double distanceFromOrigin() {
      long stamp = sl.tryOptimisticRead();
      double cx = x, cy = y;              // read without locking
      if (!sl.validate(stamp)) {          // did a writer intervene?
          stamp = sl.readLock();          // fall back to a real read lock
          try { cx = x; cy = y; }
          finally { sl.unlockRead(stamp); }
      }
      return Math.sqrt(cx*cx + cy*cy);
  }

  void move(double dx, double dy) {
      long stamp = sl.writeLock();
      try { x += dx; y += dy; }
      finally { sl.unlockWrite(stamp); }
  }

Deadlock avoidance (lock ordering)

  // BAD: different order -> deadlock
  // T1: lock A then B    T2: lock B then A

  // GOOD: global ordering (by account id)
  if (from.id < to.id) {
      from.lock.lock(); to.lock.lock();
  } else {
      to.lock.lock(); from.lock.lock();
  }
  try { /* transfer */ }
  finally {
      if (from.id < to.id) { to.lock.unlock(); from.lock.unlock(); }
      else                 { from.lock.unlock(); to.lock.unlock(); }
  }

