CAS loop (what every atomic does internally)

  // pseudocode for AtomicInteger.incrementAndGet()
  while (true) {
      int current = value;         // read
      int next    = current + 1;   // compute
      if (compareAndSet(current, next))  // CAS
          return next;             // success
      // CAS failed -> someone else changed value -> retry
  }

AtomicInteger

  AtomicInteger count = new AtomicInteger();
  count.incrementAndGet();                 // atomic ++count
  int prev = count.getAndIncrement();      // atomic count++ (returns old)
  count.compareAndSet(5, 10);              // set to 10 only if current == 5
  count.updateAndGet(v -> v * 2);          // side-effect-free lambda

  // TRAP: side-effecting lambda runs on every retry
